<script setup lang="ts">const p=withDefaults(defineProps<{value:number;max?:number;label?:string}>(),{max:100});</script><template><div class="vx-progress"><div v-if="label" class="vx-progress__caption">{{label}}</div><progress :value="Math.max(0,Math.min(p.value,p.max))" :max="p.max" :aria-label="label||'Progress'"/><span>{{Math.round(p.value/p.max*100)}}%</span></div></template>